from pathlib import Path
import hashlib,json,time
D=Path(__file__).resolve().parent;R=D.parent/'polar-rl-train'
E=R/'history/evidence/MOD4_LOCAL_NAMED_SPIN_BUTTONS_20261011';V=R/'versions/20261011_local_named_spin_buttons'
def main():
    if E.exists():raise RuntimeError('Already archived')
    test=json.loads((D/'NAMED_SPIN_BUTTON_REVIEW.json').read_text(encoding='utf8'));assert test['all_passed']
    current=json.loads((D/'INTERACTIVE_CURRENT.json').read_text(encoding='utf8'))
    start=json.loads((D/'INTERACTIVE_STARTED.json').read_text(encoding='utf8'))
    assert current['pid']==start['pid'] and 'spin_button_direction' in current and current['finite'] and current['fault'] is None
    (D/'NAMED_SPIN_BUTTONS_DEPLOYMENT_REVIEW.json').write_text(json.dumps(dict(epoch=time.time(),human_feedback='怎么小陀螺？没见小陀螺按键啊',visible_buttons=['左小陀螺 ⟲','右小陀螺 ⟳','停车 / 空格'],behavior='click starts pure spin at selected preset; stop/pause/reset/switch/focus loss clears latch',UI_real_callbacks_test=test,actual_new_player=start,actual_current=current,old_local_player_naturally_exited=True,old_runtime_source_preserved='drive_series_before_named_spin_buttons.py',native_window_reader_rejections=[dict(id='sky-original-local-window-identity-check-01',status='read rejected; no input',error='window id 6755618 no longer belongs to Microsoft.AutoGenerated.{81FC9669-044E-98D0-7435-9759BCDFC285}; current owner is Microsoft.AutoGenerated.{81FC9669-044E-98D0-7435-9759BCDFC285}'),dict(id='sky-fresh-local-window-identity-check-02',status='fresh inventory/read retry rejected; no input',error='same window identity error; old player later verified actually exited by CIM and own exit receipt')],remote_training_or_budget_changes=0,models_or_physics_changes=0),ensure_ascii=False,indent=2),encoding='utf8')
    E.mkdir(parents=True);V.mkdir(parents=True);items=[]
    files=[D/n for n in ['drive_series.py','drive_series_before_named_spin_buttons.py','verify_named_spin_buttons.py','archive_named_spin_buttons.py','README.md','NAMED_SPIN_BUTTON_REVIEW.json','NAMED_SPIN_BUTTONS_DEPLOYMENT_REVIEW.json','NAMED_BUTTONS_LAUNCH_RECEIPT.json']]
    files+=list(D.glob('BEFORE_NAMED_BUTTONS_*'))
    files+=list((D/'NAMED_SPIN_BUTTON_CHECK').glob('*.json'))
    for p in files:
        raw=p.read_bytes();sha=hashlib.sha256(raw).hexdigest();rel=p.relative_to(D)
        dest=(V if p.suffix in ('.py','.md') else E)/rel;dest.parent.mkdir(parents=True,exist_ok=True);dest.write_bytes(raw)
        items.append(dict(source_path=str(p),bytes=len(raw),source_sha256=sha,archive_path=dest.relative_to(R).as_posix(),archive_sha256=sha,archive_mode='full preserved bytes'))
    (E/'REPORT_CAPTURE_INDEX.json').write_text(json.dumps(dict(epoch=time.time(),entries=items,base_bundle_git_commit='87d6faee3b9324902bc3ccc79840c8a88ed61097',unchanged_models_and_dependencies='Reuse base version and external SHA indexes exactly'),ensure_ascii=False,indent=2),encoding='utf8')
    (E/'STAGE_NOTE.md').write_text('Human could not find the spin buttons. Added explicit left/right/stop controls next to the preset dropdown; click starts pure spin without holding keys, and stop/pause/reset/model/terrain switch/focus loss clears the latch. Visible button labels and actual callbacks through real MuJoCo control-loop were tested, including both signed directions and focus loss. No model/physics/training/canonical changes. Prior player code and own normal exit/current/start logs preserved. Native window reader rejected two identity reads with exact errors retained; no input or signal was issued. Actual old player exit was verified via CIM/own receipt before launching the updated player once. New own-PID telemetry confirms the named-button version is running. Base source, checkpoints, previous tracking residuals and trial tag remain unchanged.',encoding='utf8')
    print('Archived named-spin-buttons repair:',len(items),'files')
if __name__=='__main__':main()
